        raise "unexpected characters after value"
      }
    }
  }
  self.finalize_table(output, current_table, current_map)
  output
}

fn Parser::skip_whitespace(self: Parser) {
  while self.pos < self.input_len && (self.input[self.pos] is (' ' | '\t' | '\r')) {
    self.pos += 1
  }
}

fn Parser::skip_whitespace_and_newlines(self: Parser) {
  while self.pos < self.input_len && (self.input[self.pos] is (' ' | '\t' | '\r' | '\n')) {
    self.pos += 1
  }
}

fn Parser::skip_comment(self: Parser) {
  while self.pos < self.input_len && !(self.input[self.pos] is '\n') {
    self.pos += 1
  }
}

fn Parser::parse_table_header(self: Parser) -> (Array[String], Int) {
  // We are at '['
  self.pos += 1
  self.skip_whitespace()
  let mut keys: Array[String] = []
  loop {
    self.skip_whitespace()
    let key = self.parse_bare_key()
    keys.push(key)
    self.skip_whitespace()
