fn Parser::parse_keyval(self: Parser) -> (Array[String], Json) {
  let mut keys: Array[String] = []
  loop {
    let key = self.parse_bare_key()
    keys.push(key)
    self.skip_whitespace()
    if self.pos < self.input_len && self.input[self.pos] is '.' {
