    Json::True
  } else if ch is 'f' {
    self.expect_str("false")
    Json::False
  } else if ch is '-' || (ch is '0'..='9') {
    let n = self.parse_integer()
    Json::number(n.raw)
  } else if ch is '[' {
    self.parse_array()
  } else {
    raise "unexpected value character: \{self.input[self.pos]}"
  }
}

fn Parser::parse_integer(self: Parser) -> Int {
  let start = self.pos
  if self.pos < self.input_len && self.input[self.pos] is '-' {
    self.pos += 1
  }
  while self.pos < self.input_len && self.input[self.pos] is ('0'..='9') {
    self.pos += 1
  }
  if self.pos == start || (self.pos == start + 1 && self.input[start] is '-') {
    raise "expected integer"
  }
  @string.parse_int(self.input[start:self.pos].to_owned()).or("invalid integer")
}

fn Parser::parse_string(self: Parser) -> String {
  // We are at opening '"'
  self.pos += 1
  let start = self.pos
  let mut buf = StringBuilder::new()
  let mut escaped = false
  while self.pos < self.input_len {
    let ch = self.input[self.pos]
    if escaped {
      if ch is '"' { buf.write_char('"'); self.pos += 1; escaped = false }
      else if ch is '\\' { buf.write_char('\\'); self.pos += 1; escaped = false }
      else if ch is 'n' { buf.write_char('\n'); self.pos += 1; escaped = false }
      else if ch is 't' { buf.write_char('\t'); self.pos += 1; escaped = false }
      else { raise "invalid escape sequence: \\\{ch}" }
    } else if ch is '\\' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      escaped = true
    } else if ch is '"' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      return buf.to_string()
    } else if ch is '\n' {
      raise "newline in string"
    } else {
      self.pos += 1
    }
  }
  raise "unterminated string"
}

fn Parser::expect_str(self: Parser, expected: String) {
  let len = expected.length()
  if self.pos + len > self.input_len {
    raise "expected '\{expected}'"
  }
  for i in 0..len {
    if self.input[self.pos + i] != expected[i] {
      raise "expected '\{expected}'"
    }
  }
  self.pos += len
}

fn Parser::parse_array(self: Parser) -> Json {
  self.pos += 1 // skip '['
  self.skip_whitespace_and_newlines()
  let mut items: Array[Json] = []
  if self.pos < self.input_len && self.input[self.pos] is ']' {
    self.pos += 1
    return Json::array(items)
  }
  loop {
    self.skip_whitespace_and_newlines()
    let v = self.parse_value()
    items.push(v)
    self.skip_whitespace_and_newlines()
    if self.pos >= self.input_len {
      raise "unterminated array"
    }
    if self.input[self.pos] is ',' {
      self.pos += 1
    } else if self.input[self.pos] is ']' {
      self.pos += 1
      return Json::array(items)
    } else {
      raise "expected ',' or ']' in array"
    }
  }
}

fn Parser::insert_keys(
  self: Parser,
  map: Map[String, Json],
  keys: Array[String],
  value: Json,
) raise String {
  self._insert_keys(map, keys, 0, value)
}

fn _insert_keys(
  self: Parser,
  map: Map[String, Json],
  keys: Array[String],
  idx: Int,
  value: Json,
) raise String {
  let key = keys[idx]
  if idx == keys.length() - 1 {
    if map.contains(key) {
      raise "duplicate key: \"\{key}\""
    }
    map[key] = value
  } else {
    if map.contains(key) {
      let existing = map[key]
      match existing {
        Json::Object(inner) => {
          self._insert_keys(inner, keys, idx + 1, value)
        }
        _ => {
          raise "cannot extend non-table value at key: \"\{key}\""
        }
      }
    } else {
      let new_map: Map[String, Json] = Map::new()
      self._insert_keys(new_map, keys, idx + 1, value)
      map[key] = Json::object(new_map)
    }
  }
}

fn Parser::finalize_table(
  self: Parser,
  output: Map[String, Json],
  table_path: Array[String],
  table_map: Map[String, Json],
) {
  if table_path.length() == 0 && table_map.is_empty() {
    return
  }
  if table_path.length() == 0 {
    // Top-level keys - merge into output
    for (k, v) in table_map {
      if output.contains(k) {
        // Could be duplicate - but we already checked in insert_keys
        // Keep the first definition
      } else {
        output[k] = v
      }
    }
    return
  }
  // Navigate to the right sub-map in output
  let mut current = output
  for i in 0..table_path.length() {
    let key = table_path[i]
    if i == table_path.length() - 1 {
      if current.contains(key) {
        let existing = current[key]
        match existing {
          Json::Object(existing_map) => {
            // Merge
            for (k, v) in table_map {
              if existing_map.contains(k) {
                raise "duplicate key: \"\{k}\""
              }
              existing_map[k] = v
            }
          }
          _ => {
            raise "table key \"\{key}\" already exists as a non-table value"
          }
        }
      } else {
        current[key] = Json::object(table_map)
      }
    } else {
      if current.contains(key) {
        let existing = current[key]
        match existing {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            raise "key \"\{key}\" already exists as a non-table value"
          }
        }
      } else {
        let new_map: Map[String, Json] = Map::new()
        current[key] = Json::object(new_map)
        match current[key] {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            raise "internal error creating intermediate table"
          }
        }
      }
    }
  }
}

