///
/// Supported subset:
/// - Comments (`# ...`)
/// - Blank lines and whitespace trimming
/// - Bare keys and dotted keys
/// - Tables (`[table]`) and nested tables (`[table.sub]`)
/// - Strings with `\"`, `\\`, `\n`, `\t` escapes
/// - Integers, booleans, and arrays of those values
/// - Duplicate-key errors

priv struct Parser {
  input: String
  input_len: Int
  mut pos: Int
}

fn Parser::new(input: String) -> Parser {
  { input, input_len: input.length(), pos: 0 }
}

/// Parse TOML text into a JSON value.
///
/// Returns `Json::Object(map)` on success. Raises `String` on parse error.
pub fn parse(input: String) -> Json raise String {
  let p = Parser::new(input)
  let output: Map[String, Json] = Map::new()
  let mut current_table: Array[String] = []
  let mut current_map: Map[String, Json] = Map::new()

  while p.pos < p.input_len {
    p.skip_whitespace_and_newlines()
    if p.pos >= p.input_len {
      break
    }
    let ch = p.input[p.pos]
    if ch is '#' {
      p.skip_comment()
    } else if ch is '[' {
      // Table header
      finalize_table(output, current_table, current_map)
      let keys = p.parse_table_header()
      current_table = keys
      current_map = Map::new()
    } else if ch is '\n' {
      p.pos += 1
    } else {
      // key-value pair
      let (keys, value) = p.parse_keyval().or("expected key-value")
      p.skip_whitespace()
      // Expect newline, comment, or end-of-input
      if p.pos < p.input_len && !(p.input[p.pos] is ('\n' | '#')) {
        raise "unexpected characters after value"
      }
      if p.pos < p.input_len && p.input[p.pos] is '#' {
        p.skip_comment()
      }
      insert_keys(current_map, keys, value)?
    }
  }
  finalize_table(output, current_table, current_map)
  Json::object(output)
}

fn Parser::skip_whitespace(self: Parser) {
  while self.pos < self.input_len && (self.input[self.pos] is (' ' | '\t' | '\r')) {
    self.pos += 1
  }
}

fn Parser::skip_whitespace_and_newlines(self: Parser) {
  while self.pos < self.input_len && (self.input[self.pos] is (' ' | '\t' | '\r' | '\n')) {
    self.pos += 1
  }
}

fn Parser::skip_comment(self: Parser) {
  while self.pos < self.input_len && !(self.input[self.pos] is '\n') {
    self.pos += 1
  }
}

fn Parser::parse_table_header(self: Parser) -> Array[String] raise String {
  // We are at '['
  self.pos += 1
  self.skip_whitespace()
  let mut keys: Array[String] = []
  loop {
    self.skip_whitespace()
    let key = self.parse_bare_key()?
    keys.push(key)
    self.skip_whitespace()
    if self.pos < self.input_len && self.input[self.pos] is '.' {
      self.pos += 1
    } else {
      break
    }
  }
  self.skip_whitespace()
  if self.pos >= self.input_len || !(self.input[self.pos] is ']') {
    raise "expected ']' to close table header"
  }
  self.pos += 1
  self.skip_whitespace()
  if self.pos < self.input_len && self.input[self.pos] is '#' {
    self.skip_comment()
  }
  keys
}

fn Parser::parse_bare_key(self: Parser) -> String raise String {
  let start = self.pos
  while self.pos < self.input_len &&
    (self.input[self.pos] is ('a'..='z' | 'A'..='Z' | '0'..='9' | '-' | '_'))
  {
    self.pos += 1
  }
  if self.pos == start {
    raise "expected a key"
  }
  self.input[start:self.pos].to_owned()
}

fn Parser::parse_keyval(self: Parser) -> (Array[String], Json)? {
  let mut keys: Array[String] = []
  loop {
    let key = self.parse_bare_key().or("expected a bare key")?
    keys.push(key)
    self.skip_whitespace()
    if self.pos < self.input_len && self.input[self.pos] is '.' {
      self.pos += 1
    } else {
      break
    }
  }
  self.skip_whitespace()
  if self.pos >= self.input_len || !(self.input[self.pos] is '=') {
    return None
  }
  self.pos += 1
  self.skip_whitespace()
  let value = self.parse_value().or("expected a value")?
  Some((keys, value))
}

fn Parser::parse_value(self: Parser) -> Json? {
  if self.pos >= self.input_len {
    return None
  }
  let ch = self.input[self.pos]
  if ch is '"' {
    let s = self.parse_string()?
    Some(Json::string(s))
  } else if ch is 't' {
    self.expect_str("true")?
    Some(Json::True)
  } else if ch is 'f' {
    self.expect_str("false")?
    Some(Json::False)
  } else if ch is '-' || (ch is '0'..='9') {
    let n = self.parse_integer()?
    Some(Json::number(n.raw))
  } else if ch is '[' {
    self.parse_array()
  } else {
    None
  }
}

struct ParsedInt {
  raw: Double
}

fn Parser::parse_integer(self: Parser) -> ParsedInt? {
  let start = self.pos
  if self.pos < self.input_len && self.input[self.pos] is '-' {
    self.pos += 1
  }
  if self.pos >= self.input_len || !(self.input[self.pos] is ('0'..='9')) {
    self.pos = start
    return None
  }
  while self.pos < self.input_len && self.input[self.pos] is ('0'..='9') {
    self.pos += 1
  }
  let text = self.input[start:self.pos].to_owned()
  let n = @string.parse_int(text).or("invalid integer")
  Some({ raw: n.to_double() })
}

fn Parser::parse_string(self: Parser) -> String? {
  // We are at opening '"'
  self.pos += 1
  let start = self.pos
  let mut buf = StringBuilder::new()
  let mut escaped = false
  while self.pos < self.input_len {
    let ch = self.input[self.pos]
    if escaped {
      if ch is '"' { buf.write_char('"'); self.pos += 1; escaped = false }
      else if ch is '\\' { buf.write_char('\\'); self.pos += 1; escaped = false }
      else if ch is 'n' { buf.write_char('\n'); self.pos += 1; escaped = false }
      else if ch is 't' { buf.write_char('\t'); self.pos += 1; escaped = false }
      else { return None }
    } else if ch is '\\' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      escaped = true
    } else if ch is '"' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      return Some(buf.to_string())
    } else if ch is '\n' {
      return None
    } else {
      self.pos += 1
    }
  }
  None
}

fn Parser::expect_str(self: Parser, expected: String) -> Unit? {
  let len = expected.length()
  if self.pos + len > self.input_len {
    return None
  }
  for i in 0..len {
    if self.input[self.pos + i] != expected[i] {
      return None
    }
  }
  self.pos += len
  Some(())
}

fn Parser::parse_array(self: Parser) -> Json? {
  self.pos += 1 // skip '['
  self.skip_whitespace_and_newlines()
  let mut items: Array[Json] = []
  if self.pos < self.input_len && self.input[self.pos] is ']' {
    self.pos += 1
    return Some(Json::array(items))
  }
  loop {
    self.skip_whitespace_and_newlines()
    let v = self.parse_value()?
    items.push(v)
    self.skip_whitespace_and_newlines()
    if self.pos >= self.input_len {
      return None
    }
    if self.input[self.pos] is ',' {
      self.pos += 1
    } else if self.input[self.pos] is ']' {
      self.pos += 1
      return Some(Json::array(items))
    } else {
      return None
    }
  }
}

/// Insert value at the given key path into the map.
fn insert_keys(map: Map[String, Json], keys: Array[String], value: Json) -> Unit? {
  _insert_keys(map, keys, 0, value)
}

fn _insert_keys(map: Map[String, Json], keys: Array[String], idx: Int, value: Json) -> Unit? {
  let key = keys[idx]
  if idx == keys.length() - 1 {
    if map.contains(key) {
      return None
    }
    map[key] = value
  } else {
    if map.contains(key) {
      match map[key] {
        Json::Object(inner) => {
          _insert_keys(inner, keys, idx + 1, value)?
        }
        _ => {
          return None
        }
      }
    } else {
      let new_map: Map[String, Json] = Map::new()
      _insert_keys(new_map, keys, idx + 1, value)?
      map[key] = Json::object(new_map)
    }
  }
  Some(())
}

/// Finalize a table: merge its entries into the output at the given path.
fn finalize_table(
  output: Map[String, Json],
  table_path: Array[String],
  table_map: Map[String, Json],
) {
  if table_path.length() == 0 && table_map.is_empty() {
    return
  }
  if table_path.length() == 0 {
    // Top-level keys - merge into output
    for (k, v) in table_map {
      if !output.contains(k) {
        output[k] = v
      }
    }
    return
  }
  // Navigate to the right sub-map in output
  let mut current = output
  for i in 0..table_path.length() {
    let key = table_path[i]
    if i == table_path.length() - 1 {
      if current.contains(key) {
        match current[key] {
          Json::Object(existing_map) => {
            // Merge
            for (k, v) in table_map {
              existing_map[k] = v
            }
          }
          _ => {
            // Already exists as non-table - ignore (parse error caught elsewhere)
          }
        }
      } else {
        current[key] = Json::object(table_map)
      }
    } else {
      if current.contains(key) {
        match current[key] {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            return
          }
        }
      } else {
        let new_map: Map[String, Json] = Map::new()
        current[key] = Json::object(new_map)
        match current[key] {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            return
          }
        }
      }
    }
  }
}
