fn Parser::parse_string(self: Parser) -> String raise ParseError {
  // We are at opening '"'
  self.pos += 1
  let start = self.pos
  let mut buf = StringBuilder::new()
  let mut escaped = false
  while self.pos < self.input_len {
    let ch = self.input[self.pos]
    if escaped {
      if ch is '"' { buf.write_char('"'); self.pos += 1; escaped = false }
      else if ch is '\\' { buf.write_char('\\'); self.pos += 1; escaped = false }
      else if ch is 'n' { buf.write_char('\n'); self.pos += 1; escaped = false }
      else if ch is 't' { buf.write_char('\t'); self.pos += 1; escaped = false }
      else { raise ParseError("invalid escape sequence") }
    } else if ch is '\\' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      escaped = true
    } else if ch is '"' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      return buf.to_string()
    } else if ch is '\n' {
      raise ParseError("newline in string")
    } else {
      self.pos += 1
    }
  }
