fn Parser::expect_str(self: Parser, expected: String) -> Unit raise ParseError {
  let len = expected.length()
  if self.pos + len > self.input_len {
    raise ParseError("expected '\{expected}'")
  }
  for i in 0..len {
    if self.input[self.pos + i] != expected[i] {
      raise ParseError("expected '\{expected}'")
    }
  }
  self.pos += len
}

fn Parser::parse_array(self: Parser) -> Json raise ParseError {
  self.pos += 1 // skip '['
  self.skip_whitespace_and_newlines()
  let mut items: Array[Json] = []
  if self.pos < self.input_len && self.input[self.pos] is ']' {
    self.pos += 1
    return Json::array(items)
  }
  loop {
    self.skip_whitespace_and_newlines()
    let v = self.parse_value()
    items.push(v)
    self.skip_whitespace_and_newlines()
    if self.pos >= self.input_len {
      raise ParseError("unterminated array")
    }
    if self.input[self.pos] is ',' {
      self.pos += 1
    } else if self.input[self.pos] is ']' {
      self.pos += 1
      return Json::array(items)
    } else {
      raise ParseError("expected ',' or ']' in array")
    }
  }
}

/// Insert value at the given key path into the map.
fn insert_keys(map: Map[String, Json], keys: Array[String], value: Json) -> Unit raise ParseError {
  _insert_keys(map, keys, 0, value)
}

fn _insert_keys(map: Map[String, Json], keys: Array[String], idx: Int, value: Json) -> Unit raise ParseError {
  let key = keys[idx]
  if idx == keys.length() - 1 {
    if map.contains(key) {
      raise ParseError("duplicate key: \"\{key}\"")
    }
    map[key] = value
  } else {
    if map.contains(key) {
      match map[key] {
        Json::Object(inner) => {
          _insert_keys(inner, keys, idx + 1, value)
        }
        _ => {
          raise ParseError("cannot extend non-table value at key: \"\{key}\"")
        }
      }
    } else {
      let new_map: Map[String, Json] = Map::new()
      _insert_keys(new_map, keys, idx + 1, value)
      map[key] = Json::object(new_map)
    }
  }
}

/// Finalize a table: merge its entries into the output at the given path.
fn finalize_table(
  output: Map[String, Json],
  table_path: Array[String],
  table_map: Map[String, Json],
) -> Unit raise ParseError {
  if table_path.length() == 0 && table_map.is_empty() {
    return
  }
  if table_path.length() == 0 {
    // Top-level keys - merge into output
    for (k, v) in table_map {
      if !output.contains(k) {
        output[k] = v
      }
    }
    return
  }
  // Navigate to the right sub-map in output
  let mut current = output
  for i in 0..table_path.length() {
    let key = table_path[i]
    if i == table_path.length() - 1 {
      if current.contains(key) {
        match current[key] {
          Json::Object(existing_map) => {
            for (k, v) in table_map {
              if existing_map.contains(k) {
                raise ParseError("duplicate key: \"\{k}\"")
              }
              existing_map[k] = v
            }
          }
          _ => {
            raise ParseError("table key \"\{key}\" already exists as a non-table value")
          }
        }
      } else {
        current[key] = Json::object(table_map)
      }
    } else {
      if current.contains(key) {
        match current[key] {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            raise ParseError("key \"\{key}\" already exists as a non-table value")
          }
        }
      } else {
        let new_map: Map[String, Json] = Map::new()
        current[key] = Json::object(new_map)
        match current[key] {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            raise ParseError("internal error creating intermediate table")
          }
        }
      }
    }
  }
}
