      p.skip_whitespace()
      let after = p.cur_char()
      if let Some(c) = after {
        if c is '\n' {
          // ok, newline after value
        } else if c is '#' {
          p.skip_comment()
        } else {
          raise ParseError("unexpected characters after value")
        }
      }
      insert_keys(current_map, keys, value)
    }
  }
  finalize_table(output, current_table, current_map)
  Json::object(output)
}

