fn insert_keys(map: Map[String, Json], keys: Array[String], value: Json) -> Unit raise ParseError {
  if keys.length() == 0 {
    raise ParseError("empty key path")
  }
  let key = keys[0]
  if keys.length() == 1 {
    if map.contains(key) {
      raise ParseError("duplicate key: \"\{key}\"")
    }
    map[key] = value
  } else {
    let rest_slice = keys[1:]
    let rest: Array[String] = Array::from_iter(rest_slice.iter())
    if map.contains(key) {
      match map[key] {
        Json::Object(inner) => {
          insert_keys(inner, rest, value)
        }
        _ => {
          raise ParseError("cannot extend non-table value at key: \"\{key}\"")
        }
      }
    } else {
      let new_map: Map[String, Json] = Map::default()
      insert_keys(new_map, rest, value)
      map[key] = Json::object(new_map)
    }
  }
