/// Finalize a table: merge its entries into the output at the given path.
fn finalize_table(
  output: Map[String, Json],
  table_path: Array[String],
  table_map: Map[String, Json],
) -> Unit raise ParseError {
  if table_path.length() == 0 && table_map.is_empty() {
    return
  }
  if table_path.length() == 0 {
    table_map.each(fn(k, v) {
      if !output.contains(k) {
        output[k] = v
      }
    })
    return
  }
  let mut current = output
  for i in 0..<table_path.length() {
    let key = table_path[i]
    if i == table_path.length() - 1 {
      if current.contains(key) {
        match current[key] {
          Json::Object(existing_map) => {
            table_map.each(fn(k, v) {
              if existing_map.contains(k) {
                // We'll have the outer function raise
                raise ParseError("duplicate key: \"\{k}\"")
              }
              existing_map[k] = v
            })
          }
          _ => {
            raise ParseError("table key \"\{key}\" already exists as a non-table value")
          }
        }
      } else {
        current[key] = Json::object(table_map)
      }
    } else {
      if current.contains(key) {
        match current[key] {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            raise ParseError("key \"\{key}\" already exists as a non-table value")
          }
        }
      } else {
        let new_map: Map[String, Json] = Map::default()
        current[key] = Json::object(new_map)
        match current[key] {
          Json::Object(inner) => {
            current = inner
          }
          _ => {
            raise ParseError("internal error creating intermediate table")
          }
        }
      }
    }
  }
}
