{"path": "/private/tmp/prompt_demos/runs_flash-demos/workspaces/01/src/toml.mbt", "content": "/// Module: TOML parser — converts TOML text into a deterministic JSON value.
///
/// Supported subset:
/// - Comments (`# ...`)
/// - Blank lines and whitespace trimming
/// - Bare keys and dotted keys
/// - Tables (`[table]`) and nested tables (`[table.sub]`)
/// - Strings with `\"`, `\\`, `\n`, `\t` escapes
/// - Integers, booleans, and arrays of those values
/// - Duplicate-key errors

/// Custom error type for parse failures.
pub suberror ParseError {
  ParseError(String)
}

/// Parse TOML text into a JSON value.
///
/// Returns `Json::Object(map)` on success. Raises `ParseError` on parse error.
pub fn parse(input: String) -> Json raise ParseError {
  let p = Parser::new(input)
  let output: Map[String, Json] = Map::default()
  let mut current_table: Array[String] = []
  let mut current_map: Map[String, Json] = Map::default()

  while p.pos < p.input_len {
    p.skip_ws_newline()
    if p.pos >= p.input_len {
      break
    }
    let ch = p.char()
    if ch is '#' {
      p.skip_comment()
    } else if ch is '[' {
      finalize_table(output, current_table, current_map)
      current_table = p.parse_table_header()
      current_map = Map::default()
    } else {
      // key-value pair
      let (keys, value) = p.parse_keyval()
      p.skip_whitespace()
      let after = p.char()
      if after is '#' {
        p.skip_comment()
      } else if after is '\n' {
        // ok
      } else if after is '_' {
        // end-of-input sentinel; also ok
      } else {
        raise ParseError("unexpected characters after value")
      }
      insert_keys(current_map, keys, value)
    }
  }
  finalize_table(output, current_table, current_map)
  Json::object(output)
}

priv struct Parser {
  input: String
  input_len: Int
  mut pos: Int
}

fn Parser::new(input: String) -> Parser {
  { input, input_len: input.length(), pos: 0 }
}

/// Return the current character or '_' if past end.
fn Parser::char(self: Parser) -> Char {
  self.input.get_char(self.pos).unwrap_or(NO_CHAR)
}

/// Sentinel used when get_char returns None (past end).
const NO_CHAR : Char = '_'

fn Parser::skip_whitespace(self: Parser) -> Unit {
  while self.pos < self.input_len {
    let c = self.char()
    if c is ' ' || c is '\t' || c is '\r' {
      self.pos += 1
    } else {
      break
    }
  }
}

fn Parser::skip_ws_newline(self: Parser) -> Unit {
  while self.pos < self.input_len {
    let c = self.char()
    if c is ' ' || c is '\t' || c is '\r' || c is '\n' {
      self.pos += 1
    } else {
      break
    }
  }
}

fn Parser::skip_comment(self: Parser) -> Unit {
  while self.pos < self.input_len {
    let c = self.char()
    if c is '\n' || c is NO_CHAR {
      break
    }
    self.pos += 1
  }
}

fn Parser::parse_table_header(self: Parser) -> Array[String] raise ParseError {
  self.pos += 1 // skip '['
  self.skip_whitespace()
  let keys: Array[String] = []
  let mut first = true
  while first || self.char() is '.' {
    if !first {
      self.pos += 1
    }
    first = false
    self.skip_whitespace()
    let key = self.parse_bare_key()
    keys.push(key)
    self.skip_whitespace()
  }
  if !(self.char() is ']') {
    raise ParseError("expected ']' to close table header")
  }
  self.pos += 1
  self.skip_whitespace()
  if self.char() is '#' {
    self.skip_comment()
  }
  keys
}

fn Parser::parse_bare_key(self: Parser) -> String raise ParseError {
  let start = self.pos
  while self.pos < self.input_len {
    let c = self.char()
    if c is 'a'..='z' || c is 'A'..='Z' || c is '0'..='9' || c is '-' || c is '_' {
      self.pos += 1
    } else {
      break
    }
  }
  if self.pos == start {
    raise ParseError("expected a key")
  }
  self.input[start:self.pos].to_owned()
}

fn Parser::parse_keyval(self: Parser) -> (Array[String], Json) raise ParseError {
  let keys: Array[String] = []
  let mut first = true
  while first || self.char() is '.' {
    if !first {
      self.pos += 1
    }
    first = false
    let key = self.parse_bare_key()
    keys.push(key)
    self.skip_whitespace()
  }
  if !(self.char() is '=') {
    raise ParseError("expected '=' after key")
  }
  self.pos += 1
  self.skip_whitespace()
  let value = self.parse_value()
  (keys, value)
}

fn Parser::parse_value(self: Parser) -> Json raise ParseError {
  let ch = self.char()
  if ch is '"' {
    let s = self.parse_string()
    Json::string(s)
  } else if ch is 't' {
    self.expect_str("true")
    Json::boolean(true)
  } else if ch is 'f' {
    self.expect_str("false")
    Json::boolean(false)
  } else if ch is '-' || ch is '0'..='9' {
    let n = self.parse_integer()
    Json::number(n)
  } else if ch is '[' {
    self.parse_array()
  } else {
    raise ParseError("unexpected value character")
  }
}

fn Parser::parse_integer(self: Parser) -> Double raise ParseError {
  let start = self.pos
  if self.char() is '-' {
    self.pos += 1
  }
  let c = self.char()
  if !(c is '0'..='9') {
    self.pos = start
    raise ParseError("expected integer")
  }
  while self.pos < self.input_len {
    let ch = self.char()
    if ch is '0'..='9' {
      self.pos += 1
    } else {
      break
    }
  }
  let text = self.input[start:self.pos].to_owned()
  let n : Int = @string.parse_int(text) catch {
    _ => raise ParseError("invalid integer: \"\{text}\"")
  }
  n.to_double()
}

fn Parser::parse_string(self: Parser) -> String raise ParseError {
  self.pos += 1 // skip opening '"'
  let start = self.pos
  let buf = StringBuilder::new()
  let mut escaped = false
  while self.pos < self.input_len {
    let ch = self.char()
    if escaped {
      if ch is '"' { buf.write_char('"'); self.pos += 1; escaped = false }
      else if ch is '\\' { buf.write_char('\\'); self.pos += 1; escaped = false }
      else if ch is 'n' { buf.write_char('\n'); self.pos += 1; escaped = false }
      else if ch is 't' { buf.write_char('\t'); self.pos += 1; escaped = false }
      else { raise ParseError("invalid escape sequence") }
    } else if ch is '\\' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      escaped = true
    } else if ch is '"' {
      buf.write(self.input[start:self.pos])
      self.pos += 1
      return buf.to_string()
    } else if ch is '\n' {
      raise ParseError("newline in string")
    } else {
      self.pos += 1
    }
  }
  raise ParseError("unterminated string")
}

fn Parser::expect_str(self: Parser, expected: String) -> Unit raise ParseError {
  let len = expected.length()
  if self.pos + len > self.input_len {
    raise ParseError("expected '\{expected}'")
  }
  for i in 0..<len {
    let ec = expected.get_char(i).unwrap_or(NO_CHAR)
    if self.char() != ec {
      raise ParseError("expected '\{expected}'")
    }
    self.pos += 1
  }
}

fn Parser::parse_array(self: Parser) -> Json raise ParseError {
  self.pos += 1 // skip '['
  self.skip_ws_newline()
  let items: Array[Json] = []
  if self.char() is ']' {
    self.pos += 1
    return Json::array(items)
  }
  let mut first = true
  while !(self.char() is ']') {
    if !first {
      if self.char() is ',' {
        self.pos += 1
        self.skip_ws_newline()
      } else {
        raise ParseError("expected ',' or ']' in array")
      }
    }
    first = false
    self.skip_ws_newline()
    let v = self.parse_value()
    items.push(v)
    self.skip_ws_newline()
  }
  self.pos += 1 // skip ']'
  Json::array(items)
}

/// Insert value at the given key path into the map.
fn insert_keys(map: Map[String, Json], keys: Array[String], value: Json) -> Unit raise ParseError {
  if keys.length() == 0 {
    raise ParseError("empty key path")
  }
  let key = keys[0]
  if keys.length() == 1 {
    if map.contains(key) {
      raise ParseError("duplicate key: \"\{key}\"")
    }
    map[key] = value
  } else {
