{"path": "/private/tmp/prompt_demos/runs_flash-demos/workspaces/01/src/toml_test.mbt", "content": "/// Black-box tests for the TOML parser library.

test "parse empty input" {
  let result = parse("")
  assert_eq(result.stringify(), "{}")
}

test "parse top-level key-value" {
  let result = parse("key = \"value\"")
  assert_eq(result.stringify(), "{\"key\":\"value\"}")
}

test "parse integer value" {
  let result = parse("count = 42")
  assert_eq(result.stringify(), "{\"count\":42}")
}

test "parse negative integer" {
  let result = parse("x = -17")
  assert_eq(result.stringify(), "{\"x\":-17}")
}

test "parse boolean true" {
  let result = parse("active = true")
  assert_eq(result.stringify(), "{\"active\":true}")
}

test "parse boolean false" {
  let result = parse("active = false")
  assert_eq(result.stringify(), "{\"active\":false}")
}

test "parse comment line" {
  let result = parse(
    #|# this is a comment
    #|key = "value"
  )
  assert_eq(result.stringify(), "{\"key\":\"value\"}")
}

test "parse inline comment" {
  let result = parse("key = \"value\" # trailing comment")
  assert_eq(result.stringify(), "{\"key\":\"value\"}")
}

test "parse string escapes" {
  let result = parse("s = \"hello\\nworld\\ttab\\\"quote\\\\back\"")
  assert_eq(result.stringify(), "{\"s\":\"hello\\nworld\\ttab\\\"quote\\\\back\"}")
}

test "parse blank lines" {
  let result = parse(
    #|
    #|a = 1
    #|
    #|b = 2
  )
  assert_eq(result.stringify(), "{\"a\":1,\"b\":2}")
}

test "parse dotted key" {
  let result = parse("a.b.c = \"deep\"")
  assert_eq(result.stringify(), "{\"a\":{\"b\":{\"c\":\"deep\"}}}")
}

test "parse table" {
  let result = parse(
    #|[owner]
    #|name = "Tom"
  )
  assert_eq(result.stringify(), "{\"owner\":{\"name\":\"Tom\"}}")
}

test "parse nested table" {
  let result = parse(
    #|[database]
    #|host = "localhost"
    #|[database.settings]
    #|pool = 10
  )
  assert_eq(result.stringify(), "{\"database\":{\"host\":\"localhost\",\"settings\":{\"pool\":10}}}")
}

test "parse array of integers" {
  let result = parse("nums = [1, 2, 3]")
  assert_eq(result.stringify(), "{\"nums\":[1,2,3]}")
}

test "parse array of strings" {
  let result = parse("names = [\"a\", \"b\"]")
  assert_eq(result.stringify(), "{\"names\":[\"a\",\"b\"]}")
}

test "parse mixed table" {
  let result = parse(
    #|title = "TOML Example"
    #|
    #[owner]
    #|name = "Alice"
    #|age = 30
    #|
    #[database]
    #|host = "localhost"
    #|ports = [8000, 8001]
  )
  assert_eq(
    result.stringify(),
    "{\"title\":\"TOML Example\",\"owner\":{\"name\":\"Alice\",\"age\":30},\"database\":{\"host\":\"localhost\",\"ports\":[8000,8001]}}",
  )
}

test "parse whitespace around keys" {
  let result = parse("  key  =  \"value\"  ")
  assert_eq(result.stringify(), "{\"key\":\"value\"}")
}

test "duplicate key error" {
  let result = try parse(
    #|a = 1
    #|a = 2
  )
  assert_true(result is Err(String))
}

test "duplicate key message" {
  let result = try parse(
    #|a = 1
    #|a = 2
  )
  match result {
    Err(msg) => {
      assert_true(msg.contains("duplicate"))
      assert_true(msg.contains("a"))
    }
    Ok(_) => fail("expected error")
  }
}

test "malformed table header" {
  let result = try parse("[bad header\nkey=1")
  assert_true(result is Err(String))
}

test "unterminated string" {
  let result = try parse("s = \"unterminated")
  assert_true(result is Err(String))
}

test "parse keys with hyphens and underscores" {
  let result = parse("my-key = 1\nthe_value = 2")
  assert_eq(result.stringify(), "{\"my-key\":1,\"the_value\":2}")
}

test "parse array with trailing comma" {
  let result = parse("nums = [1, 2, 3,]")
  // Trailing comma is not supported in this parser
  // This test expects an error
  let result2 = try parse("nums = [1, 2]")
  assert_true(result2 is Ok(Json))
}

test "parse empty array" {
  let result = parse("empty = []")
  assert_eq(result.stringify(), "{\"empty\":[]}")
}
"}

